/* ═══════════════════════════ 2z · Sacred art and image: the oldest marks, images made alive, images refused and broken, pattern and plan, ideas about images, the page as image ═══════════════════════════
   What people have made to look at in worship, and what they have said about making and looking, said as carefully as the evidence allows. Each card separates what is DOCUMENTED (the earliest evidence, with its
   source) from what is only PROPOSED and what is a POPULAR STORY, says what can be seen, and gives a grade. The grade says how well an object, a practice or a claim is documented. It never says that one
   tradition’s images are better than another’s, and it never says whether an image has power. Living traditions are described and not taught. No picture on the page is copied from anywhere: the drawings on the
   Image page (2z-image-core.js) are made by the app from a rule, and no figure of a deity is drawn.
   grades are the Rites grades (RITE_GRADES in 2z-data-rites.js): attested · probable · debated · popular · mixed
   card: { id, name, kind, where, when, grade, what, earliest (documented), proposed?, popular?, look? (what can be seen), travelled?, why, care?, books [library ids], search, atlas (a text in the Atlas), site? [Atlas site ids],
           motif?, also? [card ids], draw? ('star'|'mandala'|'grid'), fig? ('signs'), elsewhere? [[href, label]] } */
const IMAGE_KINDS = { first: 'The oldest marks and figures', alive: 'Images that are made alive', refused: 'Images refused, allowed and broken', plan: 'Pattern, geometry and plan', idea: 'Ideas about images', page: 'The page as image' };
const IMAGES = [
  /* ───────────── the oldest marks and figures ───────────── */
  { id: 'blombos', name: 'Blombos: the oldest marks that look made on purpose', kind: 'first', where: 'Blombos Cave, southern Cape, South Africa', when: 'about 100,000–73,000 years ago', grade: 'mixed',
    what: 'Pieces of red ochre engraved with crossing lines, and a stone flake with a pattern drawn on it in red ochre crayon, from layers of a cave on the South African coast. They are the oldest marks yet reported that specialists widely accept as made on purpose.',
    earliest: 'Henshilwood and colleagues (Nature, 2018) described a silcrete flake from a layer dated to about 73,000 years ago, with a cross-hatched pattern of lines drawn in ochre crayon; microscopy and chemistry showed that the red had been put on deliberately. The same Middle Stone Age layers hold engraved pieces of ochre reported earlier (2002, from layers dated to about 75,000 years ago) and shell beads. The map data gives the cave’s layers as a range, about 100,000 to 71,000 years ago.',
    proposed: 'That the marks are symbols, that they carried meaning, or that they belonged to religion are inferences. A cross-hatch is not a picture of anything, and nothing beside it says what it was for.',
    look: 'Lines in a regular crossing pattern, of a kind found again at other places and times. A pattern is not a picture, and this card does not call it art in the sense of the later caves.',
    why: 'The marks, their material and their layers are documented. That they were art, symbol or religion is not.',
    books: [], search: '', site: ['blombos-cave'], also: ['neanderthal-art', 'sulawesi'] },
  { id: 'neanderthal-art', name: 'Hand stencils and a ladder shape: did Neanderthals paint?', kind: 'first', where: 'Maltravieso, La Pasiega and Ardales caves, Spain', when: 'claimed: more than 64,000 years ago', grade: 'debated',
    what: 'A 2018 study dated thin crusts of rock over red paintings in three Spanish caves to more than 64,000 years ago, before modern humans are thought to have reached Europe, and so credited the paintings to Neanderthals. Other scientists dispute the dates.',
    earliest: 'Hoffmann and colleagues (Science, 2018) used uranium-thorium dating on calcite crusts that had grown over paint: a ladder-shaped red design at La Pasiega, a hand stencil at Maltravieso and red-painted features at Ardales. They gave minimum ages of more than 64,000 years for the oldest. Modern humans are generally thought to have reached Europe about 45,000 years ago.',
    proposed: 'That the painters were Neanderthals follows from the dates alone, because no human remains lie with the paintings. Slimak and colleagues, and Pearce and Bonneau (2018), questioned the method, because uranium and thorium can move into and out of calcite after it forms; a later paper argued that leaching could make the crusts look older than they are. The original authors replied and stood by their results. The matter is unsettled.',
    popular: 'Headlines said that Neanderthals were the first artists. If the dates hold they would be the first known in Europe, and they would not be the first anywhere, because Blombos is older still; and the dates are not agreed.',
    look: 'A hand outlined in red, made by blowing or spitting paint round it; a red ladder-like shape; lines. Hand stencils are found in caves from Spain to Sulawesi to Argentina.',
    why: 'The paintings and the crusts are documented. The dates, and so who made them, are argued.',
    books: [], search: '', also: ['blombos', 'sulawesi', 'painted-caves'] },
  { id: 'sulawesi', name: 'Pigs and hunters in the caves of Sulawesi', kind: 'first', where: 'Maros-Pangkep caves, South Sulawesi, Indonesia', when: 'at least 45,000–51,000 years ago', grade: 'probable',
    what: 'Red paintings of pigs, small wild cattle and human-like figures in limestone caves on the island of Sulawesi: the oldest dated pictures of animals, and the oldest scene in which figures act together.',
    earliest: 'Brumm and colleagues (Science Advances, 2021) dated a life-size painting of a warty pig at Leang Tedongnge to at least 45,500 years ago. A hunting scene at Leang Bulu’ Sipong 4, first dated to at least 43,900 years ago (Aubert and colleagues, Nature, 2019), was re-dated in 2024 to about 48,000. Oktaviana and colleagues (Nature, 2024) reported three human-like figures with a pig at Leang Karampuang, with a minimum age of 51,200 years. All the dates come from uranium-series dating of calcite that grew over the paint, which gives a minimum age.',
    proposed: 'What the Bulu’ Sipong scene shows, a hunt, a myth or a rite, is not known. Some of its figures have animal features, and the authors read them as part-human, part-animal beings; that is an interpretation, and the same has been said of the German lion-man, which is not much younger.',
    look: 'Flat red paint: pigs, small wild cattle (anoa) and figures with animal heads or tails, often with hand stencils close by.',
    why: 'The paintings are documented and dated by a method that gives minimum ages. Their meaning, and any link to religion, is inferred.',
    books: [], search: '', site: ['leang-bulu-sipong-4', 'leang-tedongnge'], also: ['lion-man', 'neanderthal-art'] },
  { id: 'painted-caves', name: 'The painted caves of Europe, and the argument over why', kind: 'first', where: 'Chauvet, Lascaux and Altamira: France and Spain', when: 'Chauvet 37,000–28,000 years ago; Lascaux about 17,000', grade: 'mixed',
    what: 'Deep caves painted and engraved with animals, hands and signs, some far from the entrance and reached only by torchlight. Why they were made is argued; the best-known answer, that they record shamanic trance, has strong critics.',
    earliest: 'Quiles and colleagues (PNAS, 2016) modelled more than 250 radiocarbon dates from Chauvet and found two periods of human activity there, about 37,000 to 33,500 years ago and about 31,000 to 28,000 years ago, with most of the black drawings in the earlier one; the cave was later sealed by rockfalls. Lascaux, found in 1940, belongs to about 17,000 years ago and was closed to visitors in 1963 because of growths on its walls. Altamira in Spain was first published in 1880, doubted by many specialists until 1902, and its dating has been revised since.',
    proposed: 'David Lewis-Williams (The Mind in the Cave, 2002) argued that many signs and animals record the trance visions of shamans, using the rock art of the San of southern Africa as a guide. Critics such as Paul Bahn answer that the African parallel does not carry over to Europe, that the cave signs have simpler explanations, and that no one can show the painters entered trance. Earlier readings, such as hunting magic, have fared no better. None is proven.',
    popular: 'That the caves were the first churches, or that a particular painting shows a god. The caves were closed, deep places, but nothing shows that what was done in them was worship; religion is the reading that people bring.',
    look: 'Animals, mostly large ones (horses, bison, aurochs and, at Chauvet, lions, rhinoceroses and bears), outlines of hands, dots and lines, painted to follow the shape of the rock. Some are in places that are hard to reach.',
    why: 'The caves, their paintings and the dating are documented. What the painters meant, and whether it was religion, is argued.',
    books: [], search: '', site: ['chauvet-cave', 'lascaux', 'altamira'], also: ['sulawesi', 'lion-man'] },
  { id: 'lion-man', name: 'The lion-man: a figure that is neither human nor animal', kind: 'first', where: 'Hohlenstein-Stadel, Swabian Jura, Germany', when: 'about 40,000 years ago', grade: 'mixed',
    what: 'A figure about 30 cm tall, carved from mammoth ivory, with a human body and the head of a cave lion: the oldest known figure of a being that does not exist in nature.',
    earliest: 'Fragments of ivory were found in the cave in 1939, broken into very many pieces, and the figure has been put together in stages since, with more pieces from new digging. It is carved from mammoth ivory and is dated to about 40,000 years ago; sources give ranges from about 35,000 to 41,000.',
    proposed: 'It may show a human dressed as an animal, a spirit, a god or a hunter’s charm; nothing in the cave says which. Many writers call it the oldest evidence of religious imagination. That rests on the choice of an impossible creature, not on any record of what anyone believed.',
    look: 'An upright figure with human legs and arms and a lion’s head; its surface is described as worn and polished, as if handled for a long time.',
    why: 'The object, its material and its rough age are documented. That it belonged to worship is inferred from its being a creature that does not exist.',
    books: [], search: '', site: ['lion-man-of-hohlenstein-stadel'], also: ['sulawesi', 'goebekli-tepe'] },
  { id: 'goebekli-tepe', name: 'Göbekli Tepe: carved pillars before farming, and whether it was a temple', kind: 'first', where: 'near Şanlıurfa, south-eastern Turkey', when: 'about 9500–8000 BCE', grade: 'mixed',
    what: 'Rings of huge T-shaped limestone pillars, many carved with animals, built by people who had not yet farmed or made pots. The map data lists it as a sanctuary; whether that is right, or whether people also lived there, is argued.',
    earliest: 'Klaus Schmidt’s excavations (from 1995) found rings of T-shaped pillars up to about five and a half metres high, set into walls, many carved in relief with foxes, snakes, boars, birds and other animals; two central pillars in each ring have carved arms and hands and are read as stylised human figures. Radiocarbon dates put the earliest exposed structures at about 9500–9000 BCE, in the Pre-Pottery Neolithic. The enclosures were later filled in.',
    proposed: 'Schmidt called it a temple, even the first, because of the art, the labour involved and, in his view, the lack of houses. Ted Banning (2011) argued that the buildings may have been houses, and later work reports signs of everyday activity on the site. It was probably used for gatherings and rites and also for living; the balance is argued, and so is whether filling the enclosures in was deliberate.',
    popular: 'The world’s first temple, and older than Stonehenge by more than six thousand years. The site is very old and surprising, which is true; whether it is a temple is the part that is argued, and it says nothing about when writing or cities began, which was thousands of years later.',
    look: 'Animals in relief: foxes, boars, snakes, birds, scorpions; pillars with arms and hands and belts; no faces on the pillars; no writing.',
    why: 'The pillars, the carvings and the radiocarbon dates are documented. What the place was for is argued.',
    books: [], search: '', site: ['gobekli-tepe'], motif: 'sacred-place', also: ['lion-man'] },
  /* ───────────── images that are made alive ───────────── */
  { id: 'opening-mouth', name: 'Opening the mouth: how Egypt and Mesopotamia made an image live', kind: 'alive', where: 'Egypt and Mesopotamia', when: 'Egypt from the Old Kingdom to Roman times; Mesopotamian tablets of the 1st millennium BCE', grade: 'attested',
    what: 'In Egypt and Mesopotamia a statue was not a god, or a living image of the dead, until a rite had made it one. The rite was called the opening of the mouth, and the Mesopotamian texts say that the image was not made by human hands.',
    earliest: 'In Egypt the rite (wpt-r, “opening of the mouth”) was done to statues and mummies and is known from the Old Kingdom to Roman times; scenes of it are well known from tombs of the New Kingdom. Budge’s introduction to the Book of the Dead (in the library) says that rows of “coloured drawings of the offerings” were set inside coffins, offerings once presented to “the deceased or his statue” in the service of “Opening the Mouth”. In Mesopotamia the mīs pî (“washing of the mouth”) and pīt pî (“opening of the mouth”) rituals are known from tablets of the first millennium BCE, edited by Walker and Dick (2001). In them the craftsmen are made to say that they did not make the statue, their hands are symbolically cut off with a wooden knife, and the god Ea is said to have made it.',
    proposed: 'Whether the two rites are related is argued: they are far apart in place and time, and the likeness may come from facing the same problem, how to turn a made thing into a person. The same step is found elsewhere (see below), and some scholars see a single idea, others a chance likeness.',
    look: 'In tomb scenes, priests touch the mouth and eyes of a mummy-shaped figure with an adze and other tools. In the tomb, statues stand with their eyes open.',
    travelled: 'A similar step appears when the eyes of a Hindu image are opened as the last act of its installation (see the pratishtha card), when an Orthodox icon is blessed, and in the “eye-opening” ceremony for Buddha statues in Japan.',
    why: 'The Egyptian and Mesopotamian rites are documented in texts and pictures. How far they are alike, and whether one learned from the other, is not known.',
    books: ['x-bod'], search: 'Opening the Mouth', atlas: 'Opening of the Mouth ritual', motif: 'funeral-rites', also: ['tomb-painting', 'pratishtha', 'icon'] },
  { id: 'tomb-painting', name: 'Egyptian tomb painting and the grid: pictures that do the work', kind: 'alive', where: 'Egypt', when: 'from about 2600 BCE; grids from the Middle Kingdom', grade: 'attested',
    what: 'Scenes painted and carved in tombs show food, work and rites so that the dead would have them for ever. The figures follow a fixed way of showing the body, set out on a grid of squares.',
    earliest: 'Tomb scenes from the Old Kingdom on show offerings and daily life; Budge’s introduction to the Book of the Dead (in the library) describes rows of “coloured drawings of the offerings” inside coffins. The figures follow a convention often called composite: the head in profile with the eye drawn from the front, the shoulders from the front, the legs in profile. Artists set figures out on grids of squares, known from the Middle Kingdom on: a standing figure was 18 squares from the soles to the hairline in the system of the Middle and New Kingdoms, and 21 and a fraction in the Late Period (Robins, Proportion and Style in Ancient Egyptian Art, 1994). The Greek historian Diodorus, in the 1st century BCE, gives the number 21¼.',
    proposed: 'Why the style hardly changed for three thousand years is argued: tradition, the wish for a clear picture that would work for ever, or the way workshops trained. The one great break is the Amarna period, about 1350 BCE, when Akhenaten’s artists drew long faces and soft bodies and showed the sun disc, the Aten, with rays ending in hands. It is usually read as a royal order for a new way of seeing.',
    look: 'Figures in rows, in clear flat colours; each part of the body drawn from its most readable side; no shadows and no depth; writing among the figures.',
    why: 'The scenes and the grids are documented. Why the style lasted, and the reasons for Amarna, are argued.',
    books: ['x-bod'], search: 'coloured drawings', atlas: 'Great Hymn to the Aten', site: ['amarna-akhetaten'], motif: 'funeral-rites', also: ['opening-mouth', 'book-of-dead'] },
  { id: 'book-of-dead', name: 'The Book of the Dead: spells with pictures, and the weighing of the heart', kind: 'alive', where: 'Egypt', when: 'from about 1550 BCE; the Papyrus of Ani about 1250 BCE', grade: 'attested',
    what: 'Rolls of spells with painted scenes (vignettes) among the lines, placed with the dead. The best-known scene is the weighing of the heart against a feather.',
    earliest: 'The Egyptian name is “Coming Forth by Day”. Budge (in the library) says that its oldest copies on papyrus contain extracts from older funerary works such as the “Book of Opening the Mouth” and the “Liturgy of Funerary Offerings”, and that souls were weighed in the Great Scales in the Judgment Hall of Osiris, with Thoth as their advocate. The Papyrus of Ani (British Museum, about 1250 BCE) is one of the longest and best preserved, a roll of about 24 metres.',
    proposed: 'The scene of the weighing shows what the dead hoped to be able to say in their own defence. How far it matches what living Egyptians believed, as against a hope written for the tomb, is not known.',
    popular: 'That it was a single book, or the Bible of ancient Egypt. “Book of the Dead” is a modern name for many different rolls, no two alike; Budge notes that when a facsimile of one papyrus was published in 1805, French scholars described it as a copy of the “Rituel Funéraire”.',
    look: 'A line of gods and the dead in procession; scales with a heart on one pan and a feather on the other; a monster, Ammit, waiting; Thoth with his pen. Scholars treat the pictures as part of the spells, not as decoration.',
    why: 'The papyri are in museums and the texts are published. How people used them is inferred from the tombs.',
    books: ['x-bod'], search: 'Judgment Hall of Osiris', atlas: 'Papyrus of Ani', motif: 'judgment-dead', also: ['opening-mouth', 'tomb-painting'] },
  { id: 'pratishtha', name: 'Giving life to a Hindu image: the eyes opened last, and the seeing that counts', kind: 'alive', where: 'India and the Hindu world', when: 'rules in texts of the first millennium CE; practised today', grade: 'attested',
    what: 'In Hindu worship the image (murti) of a god is made by craftspeople and then made ready by a rite of installation (pratishtha), in which the god is invited to be present in it. To look at the image and to be looked at by it (darshan) is a main act of worship.',
    earliest: 'The Puranas in the library mention the rite. The Matsya Purana (in the translation by a Taluqdar of Oudh) lists the ceremonies of installing sacred images among rites that call for burnt offerings, and says that no one anxious for their own welfare should make the feet of the Sun, even in pictures or temples. The Agni Purana (Dutt’s translation) tells the worshipper to adore the seat of the image. The craft itself is set out in the shilpa shastras, which fix the proportions and poses of images by rule.',
    proposed: 'How old the rite is, and which of its parts are older than the Puranas, is argued. Pratishtha as it is now done follows later manuals of temple rites (the Agamas).',
    look: 'In the rite a priest prepares the image with water, mantras and offerings; one of its last acts is often the opening of the eyes, after which the image is the god’s body for worship.',
    care: 'Pratishtha is a living rite with its own priests and rules. This card describes it and gives no instructions.',
    why: 'The texts and the living practice are documented. The age of the rite, and how it relates to the Egyptian and Mesopotamian rites, is argued.',
    books: ['x-mtp', 'x-agp'], search: 'sacred images', motif: 'sacred-place', also: ['opening-mouth', 'icon'] },
  { id: 'icon', name: 'The icon: an image “written”, not painted, and the portrait no hand made', kind: 'alive', where: 'Byzantium, Russia, the Balkans, Egypt, Ethiopia', when: 'oldest surviving icons 6th century CE; the Mandylion story from the 5th century or later', grade: 'mixed',
    what: 'An icon is an image of Christ, Mary or a saint, made by rule, kept in church and home, and honoured with bows, kisses and lamps. In the Orthodox churches it is said to be “written”, not painted, and to be a window, not a picture.',
    earliest: 'The oldest surviving icons, at St Catherine’s monastery in Sinai, are from the 6th century. John of Damascus (in the library, volume 9 of the Nicene and Post-Nicene Fathers) answers those who “find fault with us for worshipping and honouring the image of our Saviour and that of our Lady”, and quotes Basil that “the honour given to the image passes over to the prototype” (Exact Exposition, Book 4, chapter 16). The Second Council of Nicaea (787, in the library) says that the more often images are seen, the more readily people are “lifted up to the memory of their prototypes”, and it separates the honour paid to an image from “true worship”, which belongs to God alone.',
    proposed: 'The “inverse perspective” of icons, in which lines seem to widen away from the viewer, was read by the priest and thinker Pavel Florensky (1919–1922) as a sign that the image is seen from God’s side. Many art historians answer that the effect has several causes and is not consistent. The gold ground, the halo and the flat faces are real conventions; what they mean is partly the Church’s teaching and partly later interpretation.',
    popular: 'That the portrait of Christ called the Mandylion was not made by hands. Eusebius (in the library, Church History, Book 1, chapter 13) gives the story of King Abgar of Edessa and a letter exchanged with Christ, copied from the archives of Edessa, and no portrait appears in it. A note by the library’s translators says that a later version has Ananias as an artist who tried to take the portrait of Christ. The image enters the story in later retellings, such as the Syriac Doctrine of Addai.',
    look: 'A flat, frontal figure on a gold ground, with a halo, in colours and poses that are copied from earlier icons; the faces look at the viewer.',
    care: 'Icons are objects of worship for Orthodox, Catholic and Oriental Orthodox Christians. This card describes how they are made and what is said about them and does not rank them against other images.',
    why: 'The icons, the councils and the writers are documented. What an icon means is partly doctrine and partly later reading, and the Mandylion story is a legend that grew.',
    books: ['e-m09', 'e-m14', 'e-m01'], search: 'concerning images', atlas: 'Abgar legend', also: ['byzantine-iconoclasm', 'opening-mouth', 'pratishtha'] },
  /* ───────────── images refused, allowed and broken ───────────── */
  { id: 'second-commandment', name: 'No carved image: the Hebrew Bible forbids images and commands them', kind: 'refused', where: 'Israel and Judah', when: 'the law as written down in the first millennium BCE', grade: 'attested',
    what: 'The Ten Commandments forbid making an image of anything in heaven, on earth or in the water. The same books order golden cherubim for the sanctuary and a bronze serpent, and a later king smashed that serpent because people burned incense to it.',
    earliest: 'The command is in two books of the library’s World English Bible: Exodus 20:4, “You shall not make for yourselves an idol, nor any image of anything that is in the heavens above”, and Deuteronomy 5:8. Exodus 25:18 then orders, “You shall make two cherubim of hammered gold”, for the mercy seat, and Exodus 31 says that the craftsman Bezalel is “filled with the Spirit of God” for “all kinds of workmanship”. Numbers 21 has Moses make a bronze serpent. In 2 Kings 18:4 King Hezekiah “broke in pieces the bronze serpent that Moses had made, because in those days the children of Israel burned incense to it; and he called it Nehushtan”. Isaiah 44 mocks the maker of an idol who burns part of a tree for his fire and “makes it a carved image”, and the Letter of Jeremiah (Baruch 6) does the same to “gods of silver, gold, and wood carried on shoulders”.',
    proposed: 'Whether the law first banned all images, or only images of other gods, or only images of Yahweh, is argued, and so is when it took its present form. Jewish and Christian traditions have read it differently, and both have made images in worship (see Dura-Europos). The prophets’ mockery is also read as a caricature: the Mesopotamian rites say that the image was not made by human hands (see Opening the mouth).',
    popular: 'That the ancient Israelites never made images of living things. The Bible itself shows otherwise, as the cherubim and the serpent show, and small figurines are common among finds of the period.',
    care: 'This law is read differently by Jews, Christians and Muslims, and by groups within each. The card sets out what the texts say and does not say which reading is right.',
    why: 'The texts are in the library to read. Their date and first meaning are argued.',
    books: ['b-exo', 'b-deu', 'b-2ki', 'b-isa', 'd-lje'], search: 'carved image', motif: 'name-of-god', also: ['dura-europos', 'islam-images', 'opening-mouth'] },
  { id: 'dura-europos', name: 'Dura-Europos: a synagogue and a house church, painted with people', kind: 'refused', where: 'Dura-Europos on the Euphrates (now Syria)', when: 'synagogue paintings 244–245 CE; the town fell about 256 CE', grade: 'attested',
    what: 'A synagogue whose walls are covered with scenes from the Bible, with human figures, and a house church with paintings of its own, both in a frontier town of the Roman empire. They show that worship with pictures was ordinary in some Jewish and Christian communities long before the arguments over images.',
    earliest: 'Excavations by Yale and the French Academy in the 1930s found them. The synagogue’s paintings are dated by an inscription to 244–245 CE. The town fell to the Persians about 256 CE, and the synagogue was filled with earth to strengthen the city wall, which kept its painted walls safe. The house church, a converted private house with a baptistery room, dates from about 232–256 CE; the sources differ.',
    proposed: 'Some scholars take the synagogue paintings as proof that a rule against images was not kept in ancient synagogues; others take them as a local oddity, or as an answer to a Greek-speaking world full of pictures. Their purpose, the reading of the scenes and where the artists found their models are all argued.',
    look: 'Biblical scenes in bands round the room, among them the crossing of the Red Sea and the valley of dry bones of Ezekiel; the figures face the viewer in the dress of the region; the Torah shrine is in the wall facing Jerusalem. In the house church the baptistery has a painted Good Shepherd and Adam and Eve.',
    why: 'The buildings and the paintings are documented and dated. What they show about ancient attitudes to images is argued.',
    books: ['b-exo', 'b-eze'], search: 'dry bones', site: ['dura-europos-synagogue', 'dura-europos-house-church'], also: ['second-commandment', 'icon'] },
  { id: 'buddha-aniconic', name: 'The Buddha without a body: the first images, and the argument over the absence', kind: 'refused', where: 'India and Gandhara', when: 'signs at Bharhut and Sanchi, 2nd–1st centuries BCE; images from about the 1st–2nd centuries CE', grade: 'debated',
    what: 'In the earliest surviving Buddhist art the Buddha is not shown as a man. A wheel, an empty seat under a tree, a pair of footprints or a mound stands where he would be. Images of him as a man appear some centuries after he lived. Why is argued.',
    earliest: 'The reliefs on the railings and gateways at Bharhut (about 150 BCE) and Sanchi (the gateways about the 1st century BCE) show scenes from his life and past lives with these signs and no figure of him. Alfred Foucher, early in the 20th century, called this aniconism and said that the first Buddha figures came from Gandhara under Greek influence. Figures of the Buddha appear in the 1st–2nd centuries CE at Gandhara and Mathura, and which came first is argued; they also appear on gold coins of the Kushan king Kanishka, in the 2nd century CE. The Diamond Sutra (in the library) has the Buddha say in verse that those who saw him by form, and those who heard him by sound, “engaged in false endeavours” and “will not see me”.',
    proposed: 'Susan Huntington (Art Journal, 1990) argued that a period of aniconism is a modern idea: that images were being made beside the signs, that the signs may stand for monuments and relics and not for a missing person, and that the early dates are open to question. Others, among them Vidya Dehejia and Karlsson, have defended a real early reluctance to show him. The question is not settled.',
    look: 'Four signs, drawn below as plain diagrams by the app and not copied from any carving: the wheel of the teaching, an empty seat under the tree of waking, footprints and a mound over relics.',
    travelled: 'Once images were made they spread with the religion, from Gandhara and Mathura to central Asia, China, Korea and Japan. By the time of the Lotus Sutra (in the library, Kern’s translation; the date is argued, probably around the 1st–2nd century CE) making images is itself praised: “all who caused jewel images to be made and dedicated” reached enlightenment, and so did those who ordered statues “of lead, iron, clay, or plaster” and those who made “images (of the Sugatas) on painted walls”.',
    care: 'Buddhists differ on how images are to be treated. This card describes the history and does not say which view is right.',
    why: 'The reliefs and the first images are documented. Whether the gap between them was a rule, a habit or a modern illusion is argued.',
    books: ['x-ds', 'x-sdp'], search: 'false endeavours', site: ['bharhut-stupa', 'great-stupa-sanchi'], fig: 'signs', also: ['stupa-borobudur', 'mandala'] },
  { id: 'islam-images', name: 'Images and Islam: what the texts say, and what was made', kind: 'refused', where: 'Arabia, Syria, Iran, Turkey, India', when: 'from the 7th century CE', grade: 'mixed',
    what: 'Many Muslims avoid images of living beings in places of worship, and no image of God is ever made. But the Qur’an has no plain ban on pictures, and Muslim rulers and artists made figures: on coins, in palaces, in books.',
    earliest: 'The Qur’an’s warnings are about idols. Rodwell’s English (in the library) has “wine and games of chance, and statues, and the divining arrows, are an abomination of Satan’s work” (5:90 in the usual numbering), and Pickthall’s has Jesus say, “I fashion for you out of clay the likeness of a bird, and I breathe into it and it is a bird, by Allah’s leave” (3:49). The firmer prohibitions come from sayings (hadith) collected in the 9th century, which are read differently in different schools and are not in the library. The caliph ‘Abd al-Malik had gold coins struck in 693–696 CE showing a standing figure, usually read as the caliph, then replaced them in 696–697 with coins bearing only words; later Islamic coinage is words alone. The Dome of the Rock (691–692 CE) has plant forms and a long inscription and no figures. The desert bath-house of Qusayr ‘Amra, from the early 8th century, is painted with people, and books of history and poetry from the 14th century on show people, in later ones with the face of Muhammad veiled.',
    proposed: 'Whether early Islam had a ban on images from the start, or built one up over the first two centuries, is argued. The coin reform has been linked to a quarrel with Byzantium over the image on money (one scholar suggests it followed a Byzantine envoy’s demand in 696–697); that is a hypothesis, not a settled account.',
    look: 'Calligraphy, geometry and plant forms (the arabesque) fill mosques and books where Christian churches have figures; in court and private art there are many figures.',
    care: 'Muslims differ on images by school, country and period. This card describes the texts and the history and does not say what a Muslim should do.',
    why: 'The texts, the coins and the buildings are documented. What the rules were at each time, and how far they were kept, is argued.',
    books: ['x-qur', 'x-qpk'], search: 'statues', site: ['dome-of-the-rock'], also: ['quran-calligraphy', 'islamic-geometry', 'byzantine-iconoclasm'] },
  { id: 'byzantine-iconoclasm', name: 'Iconoclasm: the Byzantine empire breaks its icons, twice, and puts them back', kind: 'refused', where: 'Constantinople and the Byzantine empire', when: 'about 726/730–787 and 815–843 CE', grade: 'attested',
    what: 'For about a hundred and ten years, with a pause, the emperors of Byzantium banned or removed religious images, and then restored them. It is the best-documented fight over holy images in history.',
    earliest: 'The usual story begins in 726 or 730 under Leo III, who is said to have removed an image of Christ from the Chalke Gate of the palace; the dates are traditional. A council at Hieria in 754 condemned images. In 787 the empress Irene’s Second Council of Nicaea reversed it, separating the honour paid to an image from the “true worship” due to God alone (in the library, The Seven Ecumenical Councils). The ban returned under Leo V in 815 and ended in 843 under the empress Theodora, remembered by the Orthodox as the Triumph of Orthodoxy. John of Damascus (died about 749) wrote from outside the emperor’s reach, under Muslim rule, that since people are made in God’s image and the tabernacle bore “an image and type of heavenly things”, honour given to an image goes to its prototype (in the library, Exact Exposition, Book 4, chapter 16).',
    proposed: 'Why Leo III acted is argued: pressure from Muslim and Jewish critics, a reading of the Second Commandment, military defeats read as God’s anger, and the emperors’ wish to control the Church have all been proposed. Some historians add that the scale of the destruction and persecution may be exaggerated, because most of what survives was written by the side that won.',
    why: 'The councils, the writings and the dates are documented. The causes, and the scale of the destruction, are argued.',
    books: ['e-m09', 'e-m14'], search: 'concerning images', site: ['hagia-sophia-cathedral'], also: ['icon', 'reformation-images', 'islam-images'] },
  { id: 'reformation-images', name: 'Breaking the images in the Reformation', kind: 'refused', where: 'Wittenberg, Zurich, Geneva, the Netherlands, England', when: '1520s–1560s, and in England the 1640s', grade: 'attested',
    what: 'In parts of 16th-century Europe reformers took the images out of churches, some by order and some by mob. Others kept them. Catholic and Orthodox churches defended them.',
    earliest: 'In 1521–22 followers of Andreas Karlstadt removed images in Wittenberg, and Luther, who held that images were harmless, preached against the violence. Zurich removed its church images by council order in 1524, Calvin’s Geneva kept them out of churches, and in the Dutch “Beeldenstorm” of 1566 crowds smashed church images in many towns. The Council of Trent’s decree of 1563 defended sacred images and told artists what to avoid. Parliament ordered images removed from English churches in 1643.',
    proposed: 'Why the reformers broke images is argued: a reading of the Second Commandment (the Reformed churches count “no carved image” as a commandment of its own, while the Lutheran and Catholic churches count it with the first), fear of idolatry, resentment at the cost and wealth of the church, and politics.',
    why: 'The events and decrees are documented. The motives of the breakers are argued.',
    books: ['b-exo'], search: 'carved image', also: ['gregory', 'second-commandment', 'byzantine-iconoclasm'] },
  /* ───────────── pattern, geometry and plan ───────────── */
  { id: 'islamic-geometry', name: 'Islamic geometric pattern: how the stars are drawn, and what they mean', kind: 'plan', where: 'from Spain to India', when: 'from the 10th century CE; most complex from the 11th to the 16th', grade: 'mixed',
    what: 'Interlocking stars, polygons and lines, repeated without end, cover mosques, tombs, books and doors in the Muslim world. How the patterns can be drawn is better known than why they were made.',
    earliest: 'Patterns of this kind appear in buildings from about the 10th century, and more complex ones from the 11th and 12th. The Topkapı Scroll (about the 15th–16th century, Topkapı Palace Museum) is a roll of pattern drawings whose lines show the grids and polygons used to set them out. Ernest Hankin (1925) described a way of drawing the patterns by putting lines at the middle of each edge of a tiling; it is the method drawn on this page. Peter Lu and Paul Steinhardt (Science, 2007) argued that craftsmen from about 1200 used five kinds of tile (girih tiles) and that the tomb tower of Darb-i Imam in Isfahan (1453) carries a pattern close to a quasicrystal. That claim is disputed: Emil Makovicky answered that the Darb-i Imam pattern is periodic, and others have read the evidence differently.',
    proposed: 'No early source that is known says what the patterns mean. Readings include the unity and endlessness of God, the order beneath things, and delight in mathematics and craft. These are modern interpretations, and the craftsmen’s own accounts, where they survive, speak of method and beauty.',
    look: 'Stars with six, eight, ten or twelve points set in networks; lines that pass over and under each other; no figures, and no centre to the whole.',
    why: 'The patterns, the scroll and the method of drawing are documented. How the craftsmen thought of them, and what they meant, is argued.',
    books: [], search: '', site: ['shah-mosque-isfahan'], draw: 'star', also: ['islam-images', 'quran-calligraphy', 'sacred-geometry'] },
  { id: 'mandala', name: 'The mandala: a palace plan that is also a map for the mind', kind: 'plan', where: 'India, Tibet, Nepal, China, Japan, Java', when: 'described from about the 7th–8th centuries CE', grade: 'mixed',
    what: 'A mandala is a circle or square plan, usually a palace with four gates inside rings, with figures at its centre. In Buddhist tantric traditions it is drawn, painted or made of coloured sand, and also built in the mind.',
    earliest: 'The word means “circle”. Mandalas for the rites of the tantras are described in texts from about the 7th–8th centuries CE, such as the Mahavairocana Sutra, and survive in painting from the first millennium. The Amitayus Meditation Sutra (in the library) is an example of building an image in the mind: “let (that image) remain clear and fixed, whether thine eyes be shut or open”. Many Tibetan mandalas share the plan drawn on this page: a square palace with four gates, within rings of lotus, vajra and fire. Sand mandalas are often swept up after the rite and the sand given to running water, which is said to teach that all things pass.',
    proposed: 'The plan is read as a palace, as a map of the world with Mount Meru at its centre, and as the mind of an enlightened being; each reading comes from the teaching of the tradition and not from the picture alone. Scholars note that the plan echoes Indian city and temple plans (see the temple grid).',
    look: 'A square with four gates, a circle at its centre, rings of lotus petals, thunderbolt sceptres and flames; the drawing on this page leaves the centre empty.',
    care: 'The mandalas of the tantras belong to initiation, and the meaning of their figures is taught to the person receiving them. This card describes the architecture that many share and does not teach; the drawing leaves the centre empty on purpose.',
    why: 'The texts, the art and the practice are documented. The meanings are part of the traditions’ own teaching, and this card does not weigh them.',
    books: ['x-amd'], search: 'clear and fixed', motif: 'meditation', draw: 'mandala', also: ['vastu', 'stupa-borobudur'] },
  { id: 'vastu', name: 'The temple grid: a square plan with the god at the centre', kind: 'plan', where: 'India', when: 'texts from about the 6th century CE; the practice is older', grade: 'probable',
    what: 'Sanskrit building texts lay a temple out on a square grid of 64 or 81 cells, with the central cells given to Brahma and the ring round them to other powers. The grid fits a rule for the plot with a picture of the world.',
    earliest: 'The building texts (vastu shastras), and works such as the Brihat Samhita of Varahamihira (6th century CE), describe the grid. Its two best-known forms are the Manduka, of 64 cells, and the Paramasayika, of 81. The sanctuary that holds the main image is built over the central cells. Stella Kramrisch’s The Hindu Temple (1946) is the standard modern account.',
    proposed: 'How far real temples follow the grid is argued: many fit it loosely, and some seem to have been laid out first and explained afterwards. That the plan is a cosmic figure, the Vastu Purusha lying across the grid, is in the texts, but temples are rarely drawn on it.',
    look: 'A square divided evenly each way; the middle cells set apart; a ring of cells round the edge.',
    travelled: 'The idea of a plan that is also a map of the world appears again in the mandala and in Buddhist stupas. In modern times vastu is also sold as advice for homes, with claims about luck and health for which there is no evidence.',
    care: 'Hindu temples are laid out and consecrated by their own priests and craftspeople. This card describes the plan and does not give rules for building.',
    why: 'The texts and the grids are documented. How far they were used, and what the plan meant to each builder, is argued.',
    books: [], search: '', motif: 'sacred-place', draw: 'grid', also: ['mandala', 'stupa-borobudur', 'sacred-geometry'] },
  { id: 'stupa-borobudur', name: 'The stupa and Borobudur: a mound that holds the Buddha, and a mountain you walk up', kind: 'plan', where: 'India, Sri Lanka, Java, Nepal, Tibet, Southeast Asia', when: 'stupas from about the 3rd century BCE; Borobudur about 780–830 CE', grade: 'mixed',
    what: 'A stupa is a mound or tower built over relics, or to mark a holy place, which Buddhists walk round. Borobudur in Java, built about 800 CE, is a stupa on a vast scale that is also a set of walkways lined with carved scenes.',
    earliest: 'Rhys Davids’s note in the library defines the thupa (stupa) as “a solid mound or tumulus or barrow, in the midst of which the bones and ashes are to be placed”. The map data places the Great Stupa at Sanchi at about 250 BCE, with its gateways later, and Borobudur at about 780–830 CE. Borobudur has nine levels, six square terraces and three round ones, topped by a central stupa, with more than two and a half thousand carved panels and about five hundred Buddha images; counts differ by source.',
    proposed: 'Borobudur has been read as a three-dimensional mandala, as a cosmic mountain, and as a pilgrimage path from scenes of ordinary life at the bottom to bare stupas at the top; the climb, the reliefs and the changing shapes are the evidence, and no text from its builders explains the plan. These are modern readings. Walking clockwise round a stupa is itself a documented practice.',
    why: 'The monuments stand and are recorded. What the builders intended is not written down.',
    books: ['x-dlb'], search: 'tumulus', site: ['great-stupa-sanchi', 'amaravati-stupa', 'borobudur'], motif: 'pilgrimage', also: ['buddha-aniconic', 'mandala', 'vastu'] },
  { id: 'sacred-geometry', name: 'Sacred geometry and the golden ratio: the numbers that are not in the buildings', kind: 'plan', where: 'modern writing about Egypt, Greece, Gothic and Islamic building', when: 'the ratio is Greek; most of the claims date from the 19th and 20th centuries', grade: 'popular',
    what: 'Many books and websites say that the pyramids, the Parthenon, cathedrals or the Flower of Life carry a hidden number, usually the golden ratio, as a sign of sacred design. Most of these claims do not hold up when the buildings are measured.',
    earliest: 'Euclid (about 300 BCE) describes dividing a line in “extreme and mean ratio”, the number now called the golden ratio, about 1.618. The name “golden” is modern, from the 19th century. Luca Pacioli’s De divina proportione (1509), with drawings by Leonardo da Vinci, praised the ratio in religious terms. Real uses of geometry in sacred building are documented elsewhere on this page: the Hindu temple grid, the mandala plan and Islamic star patterns.',
    popular: 'That the Great Pyramid, the Parthenon, Gothic cathedrals, the Mona Lisa and the Flower of Life were built to the golden ratio or encode it. George Markowsky (1992) went through many of these claims and found that the measurements were uncertain or chosen to fit, or the ratio was not there; the pyramid’s proportions can be got from other simple rules, and no Egyptian text gives the number. The circle patterns at Abydos that are called the Flower of Life are regarded by most Egyptologists as later graffiti, not part of the original design, and their date is uncertain.',
    proposed: 'That a builder used a ratio on purpose is sometimes right, and can be shown when the plans, drawings or texts say so. The test is to ask what the measurements are, who took them, and what other numbers would fit as well.',
    care: 'People find meaning in these patterns, and that is not the issue. The issue is the claim that history shows the ancients hid one number in their buildings.',
    why: 'The ratio, the book and the later claims are documented. The claims about hidden use in particular buildings are not supported.',
    books: [], search: '', also: ['islamic-geometry', 'vastu', 'mandala'] },
  /* ───────────── ideas about images ───────────── */
  { id: 'plato-image', name: 'Plato: the image is a copy of a copy', kind: 'idea', where: 'Athens', when: 'about 380 BCE', grade: 'attested',
    what: 'In the tenth book of the Republic Socrates argues that a painter makes a copy of a copy, at a third remove from what is real, and that this is why imitative art can mislead. The argument shaped later worry about images, religious and not.',
    earliest: 'In Jowett’s translation (in the library, which has the tenth book of the Republic and not the cave of the seventh) Socrates says: “Here are three beds; one in nature, which is made by God; another, which is made by the carpenter; and the third, by the painter.” The painter imitates the carpenter’s bed, not the bed itself, and so stands third from the truth.',
    travelled: 'Christian writers used arguments of this kind against pagan statues, and Neoplatonists such as Plotinus answered that a made thing can show its pattern and not only copy it.',
    why: 'Plato’s text is in the library to read. Its later influence is a matter of history, not proof.',
    books: ['x-pla'], search: 'three beds', also: ['plotinus', 'icon'] },
  { id: 'plotinus', name: 'Plotinus: refusing a portrait, and chiselling your own statue', kind: 'idea', where: 'Rome and Alexandria', when: '3rd century CE', grade: 'attested',
    what: 'The philosopher Plotinus would not let anyone make his portrait. He also gave the best-known image of inner work in ancient philosophy: shaping yourself as a sculptor carves a statue.',
    earliest: 'In the Life by his pupil Porphyry, in the library’s translation of the Enneads, Plotinus refuses a painter: “Is it not enough for me to have to carry around this image, in which nature has enclosed us?” His pupil Amelius then had the painter Carterius attend the lectures and paint him from memory. In the first Ennead the library’s translation has: “do as the artist, who cuts off, polishes, purifies until he has adorned his statue with all the marks of beauty”: the person is to remove what is superfluous and straighten what is crooked until beauty shows. Elsewhere it has him ask the reader to imagine two pieces of marble side by side, one rough and one “fashioned by the sculptor’s chisel”.',
    proposed: 'Plotinus does not condemn images: for him the beauty of a statue lies in the form the sculptor’s mind put in it and not in the stone. Later writers on images, Christian and pagan, took up the thought. How far he influenced Christian defenders of icons is argued.',
    why: 'The texts are in the library. How far later writers drew on them is argued.',
    books: ['x-plo'], search: 'sculptor', motif: 'meditation', also: ['plato-image', 'icon'] },
  { id: 'gregory', name: 'Pictures for the unlearned: Gregory the Great’s answer to an image-breaker', kind: 'idea', where: 'Rome', when: 'about 600 CE', grade: 'attested',
    what: 'Pope Gregory I wrote to a bishop who had broken the pictures in his churches that pictures do for people who cannot read what writing does for those who can. The phrase became the Western church’s standard defence of images.',
    earliest: 'In the library’s translation of Gregory’s letters (volume 13 of the Nicene and Post-Nicene Fathers), in a letter whose own note says that its main subject is the bishop’s zeal in breaking pictures of saints, Gregory writes: “to adore a picture is one thing, but to learn through the story of a picture what is to be adored is another. For what writing presents to readers, this a picture presents to the unlearned who behold, since in it even the ignorant see what they ought to follow; in it the illiterate read.” He praises the bishop for forbidding adoration of images and blames him for breaking them.',
    proposed: 'How far Gregory’s idea matches how pictures were used in churches is argued: many pictures were made for people who could read, and for kings, and the teaching of the unlearned was one use among several. Later writers, including the Council of Nicaea of 787, go further than he does.',
    why: 'The letter is in the library to read. How far it describes practice is argued.',
    books: ['e-m13'], search: 'a picture is instead of reading', also: ['reformation-images', 'icon', 'byzantine-iconoclasm'] },
  /* ───────────── the page as image ───────────── */
  { id: 'kells', name: 'The Book of Kells: a page that is worth more than its words', kind: 'page', where: 'Iona and Kells, Scotland and Ireland', when: 'about 800 CE', grade: 'probable',
    what: 'A Latin Gospel book, made about 800, whose pages are covered with knotwork, animals and figures. Its Chi Rho page spreads the first letters of Christ’s name across a whole sheet.',
    earliest: 'The manuscript was made in the early 9th century, perhaps begun on Iona and finished at Kells; where it was made is argued. It is a copy of the four Gospels in Latin with full-page pictures, kept at Trinity College Dublin. The map data lists it among its texts.',
    proposed: 'Scholars read the decoration as praise: to make the word of God beautiful is to honour it. Some see in the knots a picture of eternity, and others point to the pleasure and pride of skill. The monks who made the book are not known to have written down why.',
    why: 'The book and its approximate date are documented. The reasons for its decoration are inferred.',
    books: [], search: '', atlas: 'Book of Kells', also: ['quran-calligraphy', 'maya-codices'] },
  { id: 'quran-calligraphy', name: 'The written word as image: Arabic calligraphy', kind: 'page', where: 'the Muslim world', when: 'from the 7th–8th centuries CE; set scripts from the 10th', grade: 'attested',
    what: 'In the Muslim world the most honoured sacred image is a written one: the words of the Qur’an, in a hand made as carefully as a painting. Calligraphy is the art on walls, domes, coins and books where other traditions put pictures.',
    earliest: 'The Qur’an’s first command, in the library’s Pickthall, is “Read”, with God as the one “Who teacheth by the pen”. Early copies are in angular scripts (Hijazi, then kufic) on parchment. From the 10th century, rounded scripts such as naskh were fixed by rule, and calligraphers such as Ibn Muqla (died 940) and Ibn al-Bawwab (died 1022) are known by name. The Dome of the Rock (691–692 CE) carries one of the earliest long Qur’anic inscriptions on a building.',
    proposed: 'Calligraphy has been called the art of the word that stands in for the picture. Some writers say it grew out of a dislike of images, others that it is an art of its own that flourished beside pictures in books and buildings. The question is argued.',
    care: 'The Qur’an’s text is sacred to Muslims and its written copies are treated with care. This card describes the art and does not suggest how it should be handled.',
    why: 'The scripts, the copies and the makers are documented. Why calligraphy took the place it did is argued.',
    books: ['x-qpk'], search: 'teacheth by the pen', site: ['dome-of-the-rock'], also: ['islam-images', 'islamic-geometry', 'kells'] },
  { id: 'maya-codices', name: 'The Maya books: four survive, and a friar burned the rest', kind: 'page', where: 'Yucatán and Mexico', when: 'books of about the 11th–15th centuries; the burning at Maní in 1562', grade: 'mixed',
    what: 'The Maya wrote folding books of bark paper, painted with glyphs and pictures, on the stars, rites and days. Only a few survive. The Dresden Codex holds tables for the planet Venus.',
    earliest: 'Four Maya books are known: the Dresden, Madrid and Paris codices, and a fourth, long called the Grolier Codex and now the Codex Maya de México, whose authenticity was argued for decades. A 2018 study by Mexico’s INAH found it genuine and dated it to between 1021 and 1154 CE; some researchers still doubt it. The Dresden Codex has a table that follows the 584-day cycle of Venus as morning and evening star, with notes on rites. The Spanish friar Diego de Landa wrote in his Relación (about 1566) that, finding books in these characters containing, as he saw it, only superstition and the devil’s lies, his men burned them all at Maní in July 1562, which the Maya felt bitterly.',
    proposed: 'How the books were used, as reference manuals for priests, as ritual objects or as calendar guides, is inferred from their contents. How many books there were is not known.',
    popular: 'That the Maya predicted the end of the world in December 2012. That date was the completion of a cycle of the Long Count calendar, found on a few stone monuments; no Maya text known says that the world would end then.',
    care: 'The Maya are living peoples; the codices were made by their ancestors, and some Maya communities keep the day count today. This card describes the surviving books and does not interpret rites.',
    why: 'The books, their dates and Landa’s account are documented. Their use, and the status of the fourth, are argued.',
    books: [], search: '', atlas: 'Dresden Codex', also: ['kells', 'quran-calligraphy'] },
];
/* the Atlas places the cards point at (ids from atlas/sites.js, names as the Atlas spells them); tests/image.test.js checks that each one exists */
const IMAGE_SITES = { 'blombos-cave': 'Blombos Cave', 'leang-bulu-sipong-4': 'Leang Bulu\u2019 Sipong 4', 'leang-tedongnge': 'Leang Tedongnge', 'chauvet-cave': 'Chauvet Cave', 'lascaux': 'Lascaux', 'altamira': 'Altamira', 'lion-man-of-hohlenstein-stadel': 'Lion-man of Hohlenstein-Stadel', 'gobekli-tepe': 'G\u00f6bekli Tepe', 'amarna-akhetaten': 'Amarna (Akhetaten)', 'dura-europos-synagogue': 'Dura-Europos synagogue', 'dura-europos-house-church': 'Dura-Europos house church', 'bharhut-stupa': 'Bharhut Stupa', 'great-stupa-sanchi': 'Great Stupa, Sanchi', 'amaravati-stupa': 'Amaravati Stupa', 'borobudur': 'Borobudur', 'dome-of-the-rock': 'Dome of the Rock', 'hagia-sophia-cathedral': 'Hagia Sophia (cathedral)', 'shah-mosque-isfahan': 'Shah Mosque, Isfahan' };
const IMAGE_BY_ID = Object.fromEntries(IMAGES.map((s) => [s.id, s]));
if (typeof module !== 'undefined' && module.exports) module.exports = { IMAGE_KINDS, IMAGES, IMAGE_BY_ID, IMAGE_SITES };
